UPDATE products
SET price = ROUND(price * 0.85, 2)
WHERE category = 'Electronics';
SELECT name, price FROM products WHERE category = 'Electronics';

CREATE TABLE tasks (
  id INTEGER PRIMARY KEY,
  title TEXT NOT NULL,
  priority INTEGER NOT NULL DEFAULT 3 CHECK (priority BETWEEN 1 AND 5),
  done INTEGER NOT NULL DEFAULT 0
);
INSERT INTO tasks (title, priority) VALUES ('Write lesson', 1), ('Review quiz', 2);
INSERT INTO tasks (title) VALUES ('Tidy desk');
UPDATE tasks SET done = 1 WHERE id = 1;
SELECT * FROM tasks ORDER BY priority;

INSERT INTO customers (name, country, joined) VALUES ('Barbara Liskov', 'US', '2025-06-14');
SELECT c.id, c.name
FROM customers c
LEFT JOIN orders o ON o.customer_id = c.id
WHERE o.id IS NULL;

CREATE TABLE accounts (
  id INTEGER PRIMARY KEY,
  owner TEXT NOT NULL,
  balance REAL NOT NULL CHECK (balance >= 0)
);
INSERT INTO accounts (owner, balance) VALUES ('Ada', 100), ('Grace', 50);
BEGIN;
UPDATE accounts SET balance = balance - 25 WHERE owner = 'Ada';
UPDATE accounts SET balance = balance + 25 WHERE owner = 'Grace';
COMMIT;
SELECT owner, balance FROM accounts;
